% 清理环境
clear; clc; close all;

% 数据生成
x = (-5:0.1:5)';
% 尝试不同的函数
% y = x + 1;  % 线性
y = x.^3 + 2*x.^2 + 1;  % 非线性
% y = sin(x);  % 周期函数
% y = 1 ./ (1 + exp(-x));  % sigmoid形状

n = length(x);

% 网络结构配置
layer_sizes = [1, 5, 5, 1];  % 更大的网络
learning_rate = 0.001;
epochs = 20000;

% 初始化参数（使用Xavier初始化）
L = length(layer_sizes);
W = cell(L-1, 1);
B = cell(L-1, 1);

for i = 1:L-1
    W{i} = randn(layer_sizes(i+1), layer_sizes(i)) * sqrt(2/layer_sizes(i));
    B{i} = zeros(layer_sizes(i+1), 1);
end

% 激活函数
activation = @(x) max(0, x);  % ReLU
% activation = @(x) x;  % x
activation_deriv = @(x) double(x > 0);  % activation求导得到的函数

% 训练循环
loss_history = zeros(epochs, 1);
figure(1); clf;

for epoch = 1:epochs
    % 前向传播
    Z = cell(L-1, 1);
    A = cell(L, 1);
    A{1} = x';  % 输入  直接输入所有样本
    
    for i = 1:L-2
        Z{i} = W{i} * A{i} + B{i};
        A{i+1} = activation(Z{i});
    end
    
    % 输出层（线性激活） 
    Z{L-1} = W{L-1} * A{L-1} + B{L-1};
    A{L} = Z{L-1};
    
    % 计算损失
    y_pred = A{L}';
    loss = mean((y_pred - y).^2);
    loss_history(epoch) = loss;
    
    % 反向传播
    dW = cell(L-1, 1);
    dB = cell(L-1, 1);
    
    % 输出层梯度  所有样本取平均
    dZ = (A{L} - y') / n;
    dW{L-1} = dZ * A{L-1}';
    dB{L-1} = sum(dZ, 2);
    
    % 隐藏层梯度   也是所有样本的平均梯度
    for i = L-2:-1:1
        dZ = (W{i+1}' * dZ) .* activation_deriv(Z{i});
        dW{i} = dZ * A{i}';
        dB{i} = sum(dZ, 2);
    end
    
    % 更新参数
    for i = 1:L-1
        W{i} = W{i} - learning_rate * dW{i};
        B{i} = B{i} - learning_rate * dB{i};
    end
    
    % 动态显示
    if mod(epoch, 500) == 0
        fprintf('Epoch %d, Loss: %.6f\n', epoch, loss);
        
        % 实时绘图
        subplot(2,2,1);
        plot(x, y, 'b-', 'LineWidth', 2); hold on;
        plot(x, y_pred, 'r--', 'LineWidth', 2); hold off;
        xlabel('x'); ylabel('y');
        title(sprintf('拟合结果 (Epoch %d)', epoch));
        legend('真实值', '预测值');
        grid on;
        
        subplot(2,2,2);
        semilogy(loss_history(1:epoch));
        xlabel('Epoch'); ylabel('Loss (log)');
        title('损失曲线'); grid on;
        
        subplot(2,2,3);
        error = y_pred - y;
        plot(x, error);
        xlabel('x'); ylabel('误差');
        title('预测误差'); grid on;
        
        subplot(2,2,4);
        bar([W{1}(:); W{2}(:); W{3}(:); B{1}(:); B{2}(:); B{3}(:)]);
        xlabel('参数索引'); ylabel('值');
        title('参数分布'); grid on;
        
        drawnow;
    end
end

% 最终评估
y_pred_final = y_pred;
fprintf('\n训练完成！\n');
fprintf('最终损失: %.6f\n', loss);
fprintf('最大绝对误差: %.6f\n', max(abs(y_pred_final - y)));
fprintf('平均绝对误差: %.6f\n', mean(abs(y_pred_final - y)));

%%
%% 1. 数据准备
x = (-5:0.1:5)';
y = x.^3 + 2*x.^2 + 1; % 目标函数

% 划分训练集和测试集 (简单起见，这里直接用全部数据)
xTrain = x;
yTrain = y;

%% 2. 定义网络结构 (1-5-5-1)
layers = [
    featureInputLayer(1, 'Name', 'input')
    
    fullyConnectedLayer(5, 'Name', 'fc1')
    reluLayer('Name', 'relu1')
    
    fullyConnectedLayer(5, 'Name', 'fc2')
    reluLayer('Name', 'relu2')
    
    fullyConnectedLayer(1, 'Name', 'output')
    regressionLayer('Name', 'loss') % 回归层计算 MSE
];

%% 3. 配置训练参数
options = trainingOptions('adam', ...      % 使用 Adam 优化器 (比基础 SGD 更快)
    'MaxEpochs', 5000, ...                 % 最大迭代次数
    'MiniBatchSize', length(xTrain), ...   % 每次迭代使用的数据量
    'InitialLearnRate', 0.01, ...          % 初始学习率
    'Shuffle', 'every-epoch', ...          % 每轮打乱数据
    'Plots', 'training-progress', ...      % 显示训练实时图表
    'Verbose', false);

%% 4. 训练网络
net = trainNetwork(xTrain, yTrain, layers, options);

%% 5. 预测与评估
yPred = predict(net, xTrain);

% 计算性能指标
mseValue = mean((yPred - yTrain).^2);
maeValue = mean(abs(yPred - yTrain));

fprintf('\n工具箱训练完成！\n'); %[output:24dc9f0d]
fprintf('最终损失 (MSE): %.6f\n', mseValue); %[output:353a68ef]
fprintf('平均绝对误差 (MAE): %.6f\n', maeValue); %[output:3c1092b1]

%% 6. 结果可视化
figure; %[output:8e47bd14]
subplot(1,2,1); %[output:8e47bd14]
plot(xTrain, yTrain, 'b-', 'LineWidth', 2); hold on; %[output:8e47bd14]
plot(xTrain, yPred, 'r--', 'LineWidth', 2); %[output:8e47bd14]
grid on; %[output:8e47bd14]
legend('真实值', '神经网络预测'); %[output:8e47bd14]
title('拟合结果对比'); %[output:8e47bd14]
xlabel('x'); ylabel('y'); %[output:8e47bd14]

subplot(1,2,2); %[output:8e47bd14]
error = yPred - yTrain;
stem(xTrain, error); %[output:8e47bd14]
grid on; %[output:8e47bd14]
title('预测残差 (Residuals)'); %[output:8e47bd14]
xlabel('x'); ylabel('误差'); %[output:8e47bd14]

